#!/usr/bin/env python3
"""Q241: docs/pose_rom_table.md from scripts/anatomy/q241/rom.py (the single source of the slider bounds). tests/test_q241_rom.py checks the file is up to date."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from rom import ROM, spine_weights

REPO = Path(__file__).resolve().parents[3]
OUT = REPO / "docs/pose_rom_table.md"
GROUPS = [("Shoulder (glenohumeral + scapulothoracic, as measured clinically)", "shoulder_"), ("Elbow and forearm", ("elbow_", "forearm_")), ("Wrist", "wrist_"), ("Thumb", "thumb_"),
          ("Fingers (index to little)", "finger_"), ("Hip", "hip_"), ("Knee", "knee_"), ("Ankle and subtalar", "ankle_"), ("Toes", ("toe_", "toe1_")),
          ("Cervical spine / head", "cerv_"), ("Thoracic spine", "thor_"), ("Lumbar spine", "lumb_")]


def render() -> str:
    L = ["# Normal range of motion used by the Pose panel (Q241)\n"]
    L.append("Source of truth: `scripts/anatomy/q241/rom.py` (this file is generated by `scripts/anatomy/q241/make_rom_doc.py`; `tests/test_q241_rom.py` fails when it is out of date).\n")
    L.append("## What these numbers are\n")
    L.append("* **Population averages** of the active / passive range of motion of healthy young adults, in degrees, in the style of the AAOS (American Academy of Orthopaedic Surgeons, *Joint Motion: Method of Measuring and Recording*, 1965; "
             "Greene & Heckman, *The Clinical Measurement of Joint Motion*, AAOS 1994) and the AMA *Guides to the Evaluation of Permanent Impairment* (5th / 6th ed.); Norkin & White, *Measurement of Joint Motion: A Guide to Goniometry* "
             "(5th ed. 2016); Kapandji, *The Physiology of the Joints*; for the spine split between regions White & Panjabi, *Clinical Biomechanics of the Spine* (2nd ed. 1990). Hip / knee / ankle / shoulder / elbow / wrist values are the "
             "commonly quoted AAOS values.")
    L.append("* **Quoted from memory.** These books were NOT re-read in the session that wrote this table; the values are the widely quoted ones and several differ between the AAOS and the AMA tables by 5-20 degrees "
             "(noted in the entries). Treat them as typical values, not as a clinical reference. An individual's range depends on age, sex, body build, and on the measuring method (active / passive, "
             "goniometer, with or without scapular fixation). Nothing here is a clinical norm for a patient.")
    L.append("* Entries marked **ASSUMPTION** are modelling choices where no single standard value exists (the shoulder adduction limit, the per-level split of the spinal ranges, DIP flexion, the lesser-toe ranges, "
             "the thumb CMC ranges, the sign / zero conventions of the displayed values).")
    L.append("* The slider range is the HARD bound of what the user can set. A slider shows the shaded normal range, a tick at the model's own pose and a faint line at 0. If the model's own pose lies slightly outside the normal "
             "range (a hyperextended knee of a few degrees, for example) it is shown as it is and can only be moved into the range.")
    L.append("* Zero conventions: neutral anatomical position (arms at the sides, palms forward, elbows / knees extended, feet at right angles to the shank); forearm rotation 0 = neutral (thumb forward), + = supination; "
             "the spine and head are measured from the posture as built (zero = the model's own spine).\n")
    L.append("## Ranges (degrees)\n")
    for title, pref in GROUPS:
        keys = [k for k in ROM if k.startswith(pref if isinstance(pref, str) else pref)]
        if not keys:
            continue
        L.append("### %s\n" % title)
        L.append("| displayed value | range | source / assumption |\n|---|---|---|")
        for k in keys:
            lo, hi, lab, src = ROM[k]
            L.append("| %s | %g to %g | %s |" % (lab, lo, hi, src))
        L.append("")
    L.append("## Per-level split of the spinal ranges (ASSUMPTION)\n")
    L.append("A regional slider (lumbar, thoracic, head / neck) moves every level joint of the region by a fixed share of the total. Equal shares, except: cervical rotation 50% at C1/C2 and the rest shared by C2-T1 "
             "(White & Panjabi report about half of the cervical rotation at the atlanto-axial joint); the occiput / C1 joint takes 20% of the cervical flexion-extension arc. "
             "Example shares: cervical flexion " + ", ".join("%.2f" % w for w in spine_weights("cervical", ["OCC", "C1", "C2", "C3", "C4", "C5", "C6", "C7"], "flex")) +
             " (occiput, C1 ... C7); cervical rotation " + ", ".join("%.2f" % w for w in spine_weights("cervical", ["OCC", "C1", "C2", "C3", "C4", "C5", "C6", "C7"], "rot")) + ".\n")
    L.append("## Joint mechanics in the Pose panel (what each slider moves)\n")
    L.append("* Joint centres and axes are computed from the page's OWN bones (`scripts/anatomy/q241/skeleton.py`, `rig.py`): hip and shoulder = sphere fit of the femoral / humeral head; elbow and knee = transepicondylar axis "
             "(sign from the radius / fibula, valid for any limb rotation); forearm = line radial head - ulnar head; wrist = centroid of the proximal carpals; fingers / toes = distal-end sphere / centroid of each bone; ankle = malleolar axis; "
             "subtalar = Inman's axis (42 deg above the horizontal, 23 deg medial to the foot axis) in the foot frame (literature axis, not fitted); spine = disc centres between the vertebral centroids; the fit errors are in `data/derived/Q241_rig_<page>.json`.")
    L.append("* Shoulder and hip: three angles in the order flexion (about the mediolateral axis), abduction (about the anteroposterior axis), rotation (about the bone's long axis), relative to the trunk / pelvis frame (intrinsic order; "
             "at 90 deg abduction flexion and rotation become the same motion - the usual Cardan singularity). Clavicle and scapula follow the shoulder with a fixed scapulohumeral rhythm (1/12 of the humeral elevation at the clavicle, 1/4 at the scapula, "
             "together 1/3 = the 2:1 glenohumeral : scapulothoracic ratio, Inman 1944 - ASSUMPTION: linear, no 30 deg setting phase). The patella follows 60% of the knee flexion angle (ASSUMPTION).")
    L.append("* Imaging-based pages: the bone meshes of all phalanges / metatarsals are merged into one mesh and cannot be separated reliably, so the fingers and toes are NOT articulated there (hand and foot move as one segment); "
             "Base and Combined pages have the individual bones and articulate thumb, index to little finger (MCP, PIP, DIP) and all toes.")
    L.append("* Not modelled: tibial rotation / screw-home, scapular and clavicular manual controls, finger abduction, jaw (TMJ), rib cage excursion, intercarpal motion, any soft-tissue collision or volume preservation.\n")
    return "\n".join(L) + "\n"


if __name__ == "__main__":
    OUT.write_text(render(), encoding="utf-8")
    print("wrote", OUT)
